const DistillationVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        const particles: any[] = [];
        for(let i=0; i<60; i++) {
            particles.push({
                x: Math.random() * w,
                y: Math.random() * h,
                r: Math.random() * 3 + 1,
                speed: 0.5 + Math.random() * 1.5,
                wobble: Math.random() * Math.PI * 2
            });
        }

        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            ctx.clearRect(0,0,w,h);

            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(w*0.3, 0); ctx.lineTo(w*0.3, h);
            ctx.moveTo(w*0.7, 0); ctx.lineTo(w*0.7, h);
            ctx.stroke();

            [0.2, 0.4, 0.6, 0.8].forEach(lvl => {
                ctx.beginPath(); ctx.moveTo(w*0.3, h*lvl); ctx.lineTo(w*0.7, h*lvl); ctx.stroke();
            });

            particles.forEach(p => {
                p.y -= p.speed;
                p.x += Math.sin(p.y * 0.05 + p.wobble) * 0.5;
                if (p.y < 0) {
                    p.y = h + 10;
                    p.x = w*0.35 + Math.random() * (w*0.3);
                }
                if(p.x < w*0.32) p.x = w*0.32;
                if(p.x > w*0.68) p.x = w*0.68;

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.2 + (p.y / h) * 0.6;
                ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill();
            });
            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const GridSyncVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMove = (e: MouseEvent) => {
            if (canvasRef.current) {
                const r = canvasRef.current.getBoundingClientRect();
                mouseRef.current = { x: e.clientX - r.left, y: e.clientY - r.top };
            }
        };
        const el = canvasRef.current;
        if(el) el.addEventListener('mousemove', handleMove);
        return () => { if(el) el.removeEventListener('mousemove', handleMove); }
    }, []);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        let t = 0;
        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            t += 0.05;
            ctx.clearRect(0,0,w,h);

            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            for(let x=0; x<w; x+=5) {
                const dist = Math.abs(x - mouseRef.current.x);
                const influence = Math.max(0, 1 - dist/100) * 20;
                const y = h/2 + Math.sin(x * 0.03 + t) * 40 + influence;
                if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.stroke();

            ctx.beginPath();
            ctx.strokeStyle = 'rgba(255,255,255,0.15)'; 
            for(let x=0; x<w; x+=5) {
                const dist = Math.abs(x - mouseRef.current.x);
                const influence = Math.max(0, 1 - dist/100) * 20;
                const y = h/2 + Math.sin(x * 0.03 + t + 0.5) * 40 - influence; 
                if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.stroke();

            if (Math.sin(t) > 0.9) {
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(w/2, h/2 + 40, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(w/2, h/2 - 40, 3, 0, Math.PI*2); ctx.fill();
            }

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const GeologicalScanVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        let t = 0;
        let frameId: number;

        const ores = Array.from({length: 10}, () => ({
            x: Math.random() * 300,
            y: 50 + Math.random() * 250,
            val: Math.random()
        }));

        const layers = [
            { y: 50, color: '#222' },
            { y: 120, color: '#1a1a1a' },
            { y: 200, color: '#111' },
            { y: 280, color: '#050505' }
        ];

        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            t += 2;
            ctx.clearRect(0,0,w,h);

            layers.forEach(l => {
                ctx.fillStyle = l.color;
                ctx.fillRect(0, l.y, w, 80);
            });

            ores.forEach(o => {
                ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
                ctx.beginPath(); ctx.arc(o.x, o.y, 3, 0, Math.PI*2); ctx.fill();
            });

            const bx = w/2 - 20;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(bx, 0, 40, h);
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.strokeRect(bx, 0, 40, h);

            const scanY = t % h;
            ctx.fillStyle = color;
            ctx.shadowBlur = 15; ctx.shadowColor = color;
            ctx.fillRect(bx - 10, scanY, 60, 2);
            ctx.shadowBlur = 0;

            ores.forEach(o => {
                if (Math.abs(o.y - scanY) < 20 && Math.abs(o.x - w/2) < 50) {
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 10; ctx.shadowColor = '#fff';
                    ctx.beginPath(); ctx.arc(o.x, o.y, 5, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
                    ctx.beginPath(); ctx.moveTo(w/2, scanY); ctx.lineTo(o.x, o.y); ctx.stroke();
                }
            });

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const WaterVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        const particles: any[] = [];
        for(let i=0; i<50; i++) particles.push({ x: Math.random()*w, y: Math.random()*h, speed: 1+Math.random() });

        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            ctx.clearRect(0,0,w,h);

            // Filter Barrier
            ctx.fillStyle = 'rgba(255,255,255,0.1)';
            ctx.fillRect(w/2 - 2, 0, 4, h);

            particles.forEach(p => {
                p.x += p.speed;
                if(p.x > w) p.x = 0;

                // Color change across filter
                ctx.fillStyle = p.x < w/2 ? '#555' : color;
                ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI*2); ctx.fill();
            });

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

