// --- CAROUSEL COMPONENT ---
const IndustryCarousel: React.FC = () => {
    const [activeIndex, setActiveIndex] = useState(0);
    const count = INDUSTRIES.length;

    const next = () => setActiveIndex((prev) => (prev + 1) % count);
    const prev = () => setActiveIndex((prev) => (prev - 1 + count) % count);

    const activeItem = INDUSTRIES[activeIndex];

    return (
        <div className="relative w-full h-[700px] flex items-center justify-center overflow-hidden">

            {/* Dynamic Background */}
            <div 
                className="absolute inset-0 transition-all duration-1000 ease-in-out pointer-events-none"
                style={{
                    background: `radial-gradient(circle at 50% 50%, ${activeItem.color}20, transparent 70%)`
                }}
            />

            {/* Cards Container */}
            <div className="relative w-full max-w-7xl h-full mx-auto">
                {INDUSTRIES.map((item, index) => {
                    let offset = (index - activeIndex);
                    if (offset < -Math.floor(count / 2)) offset += count;
                    if (offset > Math.floor(count / 2)) offset -= count;

                    const isActive = offset === 0;
                    const isVisible = Math.abs(offset) <= 1; // Strict optimization: Only load active and adjacent

                    if (!isVisible) return null;

                    const zIndex = isActive ? 20 : 10 - Math.abs(offset);
                    const opacity = isActive ? 1 : 0.4;
                    const scale = isActive ? 1 : 0.85;
                    const translateX = offset * 110; 

                    return (
                        <div 
                            key={item.id}
                            className="absolute top-1/2 left-1/2 w-[85vw] max-w-[340px] md:max-w-none md:w-[400px] h-[500px] transition-all duration-700 cubic-bezier(0.25, 0.8, 0.25, 1) cursor-pointer"
                            style={{
                                transform: `translate(-50%, -50%) translateX(${translateX}%) scale(${scale})`,
                                zIndex,
                                opacity
                            }}
                            onClick={() => {
                                if (!isActive) setActiveIndex(index);
                            }}
                        >
                            <div className="relative w-full h-full rounded-3xl bg-[#0c0c0e] overflow-hidden shadow-2xl group border border-white/10 hover:border-white/20 transition-colors">

                                {/* Visualizer - CONDITIONAL RENDERING */}
                                <div className={`absolute inset-0 transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-40 grayscale'}`}>
                                    {isActive ? (
                                        <item.Visualizer />
                                    ) : (
                                        <div className="absolute inset-0 bg-black/40" /> 
                                    )}
                                </div>

                                {/* Content Overlay */}
                                <div className="absolute inset-0 p-8 flex flex-col justify-end bg-gradient-to-t from-black via-black/50 to-transparent">
                                    <div className={`transition-all duration-500 transform ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-80'}`}>
                                        <div className="flex items-center gap-3 mb-4 text-[var(--card-color)]" style={{'--card-color': item.color} as any}>
                                            <div className="p-2 rounded-lg bg-white/10 backdrop-blur-sm">
                                                <item.icon size={20} />
                                            </div>
                                            <span className="text-xs font-bold uppercase tracking-widest">{item.subtitle}</span>
                                        </div>

                                        <h3 className="text-3xl md:text-4xl font-serif text-white mb-4 leading-none">{item.title}</h3>
                                        <p className="text-sm text-white/70 leading-relaxed mb-8 line-clamp-3">
                                            {item.desc}
                                        </p>
                                    </div>
                                </div>

                                {isActive && (
                                    <div 
                                        className="absolute inset-0 rounded-3xl pointer-events-none border-2 border-[var(--card-color)] opacity-50 shadow-[0_0_30px_var(--card-color)] transition-all"
                                        style={{'--card-color': item.color} as any}
                                    />
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            <button onClick={prev} className="absolute left-4 md:left-12 z-30 p-4 rounded-full bg-white/5 hover:bg-white/10 border border-white/10 text-white backdrop-blur-md transition-all active:scale-95">
                <ChevronLeft size={24} />
            </button>
            <button onClick={next} className="absolute right-4 md:right-12 z-30 p-4 rounded-full bg-white/5 hover:bg-white/10 border border-white/10 text-white backdrop-blur-md transition-all active:scale-95">
                <ChevronRight size={24} />
            </button>
        </div>
    );
};

// --- SECRET TERMINAL BUTTON (PARTICLE EFFECT) ---
const SecretTerminalButton: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const particlesRef = useRef<any[]>([]);

    // Config
    const W = 400; // Canvas size
    const H = 400;
    const CENTER = W / 2;

    const handleClick = () => {
        const count = 30;
        const chars = ['0', '1', '>', '_', '/', 'X', ':', '.'];

        for (let i = 0; i < count; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = 2 + Math.random() * 8;

            // Standard particles
            particlesRef.current.push({
                x: CENTER, 
                y: CENTER,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                life: 1.0,
                color: Math.random() > 0.6 ? '#69B7B2' : (Math.random() > 0.5 ? '#f59e0b' : '#ffffff'),
                size: Math.random() * 3 + 1,
                type: 'particle'
            });

            // Code fragments
            if (i % 3 === 0) {
                particlesRef.current.push({
                    x: CENTER, 
                    y: CENTER,
                    vx: Math.cos(angle) * (speed * 0.8),
                    vy: Math.sin(angle) * (speed * 0.8),
                    life: 1.2, // Live slightly longer
                    color: '#69B7B2',
                    char: chars[Math.floor(Math.random() * chars.length)],
                    type: 'text'
                });
            }
        }

        // Add Rings
        particlesRef.current.push({
            x: CENTER, y: CENTER, r: 25, maxR: 160, alpha: 1, type: 'ring', color: '#ffffff', width: 2
        });
        particlesRef.current.push({
            x: CENTER, y: CENTER, r: 25, maxR: 130, alpha: 0.8, type: 'ring', color: '#69B7B2', width: 4
        });
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Fix resolution
        canvas.width = W;
        canvas.height = H;

        let frameId: number;

        const render = () => {
            ctx.clearRect(0, 0, W, H);

            // Iterate backwards to remove dead particles safely
            for (let i = particlesRef.current.length - 1; i >= 0; i--) {
                const p = particlesRef.current[i];

                if (p.type === 'particle') {
                    p.x += p.vx;
                    p.y += p.vy;
                    p.life -= 0.02;
                    p.vx *= 0.94; // friction
                    p.vy *= 0.94;

                    if (p.life <= 0) {
                        particlesRef.current.splice(i, 1);
                        continue;
                    }

                    ctx.globalAlpha = p.life;
                    ctx.fillStyle = p.color;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                    ctx.fill();

                } else if (p.type === 'text') {
                    p.x += p.vx;
                    p.y += p.vy;
                    p.life -= 0.015;

                    if (p.life <= 0) {
                        particlesRef.current.splice(i, 1);
                        continue;
                    }

                    ctx.globalAlpha = p.life;
                    ctx.fillStyle = p.color;
                    ctx.font = '10px monospace';
                    ctx.fillText(p.char, p.x, p.y);

                } else if (p.type === 'ring') {
                    p.r += (p.maxR - p.r) * 0.15; // Ease out
                    p.alpha -= 0.04;

                    if (p.alpha <= 0) {
                        particlesRef.current.splice(i, 1);
                        continue;
                    }

                    ctx.globalAlpha = p.alpha;
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = p.width;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
                    ctx.stroke();
                }
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        render();
        return () => cancelAnimationFrame(frameId);
    }, []);

    return (
        <div className="relative group w-20 h-20 mx-auto mb-8 cursor-pointer z-10" onClick={handleClick}>
            {/* Canvas Layer - Centered over button but larger to allow spillover */}
            <canvas 
                ref={canvasRef} 
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none" 
                style={{ width: '400px', height: '400px' }}
            />

            {/* The Button */}
            <div className="relative w-full h-full bg-white/5 border border-white/10 rounded-full flex items-center justify-center text-white/50 group-hover:bg-white/10 group-hover:text-white group-hover:scale-110 transition-all duration-200 shadow-[0_0_0_0_rgba(255,255,255,0)] group-active:shadow-[0_0_30px_rgba(105,183,178,0.4)] group-active:scale-95 z-20 overflow-hidden animate-pulse group-hover:animate-none">
                <div className="absolute inset-0 bg-gradient-to-tr from-white/0 via-white/5 to-white/0 opacity-0 group-hover:opacity-100 transition-opacity" />
                <Terminal size={32} />
            </div>
        </div>
    );
};

